from datetime import date, timedelta


class Loyalty:
    def __init__(self) -> None:
        # customer -> list of (available_on, points_remaining)
        self._earned = {}
        # customer -> total points already redeemed
        self._redeemed = {}

    def purchase(self, customer: str, amount: float, day: date) -> int:
        # 1 point per full 10.00 spent
        points = int(amount // 10)
        if points > 0:
            available_on = day + timedelta(days=14)
            self._earned.setdefault(customer, []).append([available_on, points])
        return points

    def balance(self, customer: str, day: date) -> int:
        total = 0
        for entry in self._earned.get(customer, ()):
            available_on, remaining = entry
            if available_on <= day:
                total += remaining
        return total

    def redeem(self, customer: str, points: int, day: date) -> None:
        if points % 100 != 0:
            raise ValueError("Points can only be redeemed in multiples of 100")
        available = self.balance(customer, day)
        if points > available:
            raise ValueError("Insufficient available points")

        # Deduct from oldest-available buckets first
        to_deduct = points
        for entry in self._earned.get(customer, ()):
            if to_deduct == 0:
                break
            available_on, remaining = entry
            if available_on <= day and remaining > 0:
                take = min(remaining, to_deduct)
                entry[1] -= take
                to_deduct -= take

        self._redeemed[customer] = self._redeemed.get(customer, 0) + points
